package com.muxigame.city;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;
import net.neoforged.neoforge.network.PacketDistributor;

/** Administrator authoring only. The template deliberately contains no identity, assets or simulation progress. */
public final class CityNpcDesigner {
 static final String KEY="CityCareerTemplate";
 static final List<RuralRules.Role> ROLES=List.of(RuralRules.Role.FARMER,RuralRules.Role.COOK,RuralRules.Role.HUNTER,RuralRules.Role.MERCHANT,RuralRules.Role.PROCUREMENT,RuralRules.Role.BAKER,RuralRules.Role.SUPPLIER,RuralRules.Role.ARTISAN,RuralRules.Role.NONE);
 public static final class Template {
  public int schema=1;public String name="新居民",skin="";public RuralRules.Role role=RuralRules.Role.FARMER;public boolean female;
  public int start=6,end=18,nightStart=18,nightEnd=6,willingness=25,huntRadius=128;
 }
 record Session(UUID npc,BlockPos anchor,String dimension,long token,long expires){}
 private static final Map<UUID,Session> sessions=new HashMap<>();
 private static long serial;
 static boolean wand(ItemStack stack){return BuiltInRegistries.ITEM.getKey(stack.getItem()).toString().equals("customnpcs:npcmobcloner");}
 static void access(ServerPlayer p){RuralTools.editor(p);CityEconomy.require(wand(p.getMainHandItem()),"请手持复制魔杖");}
 static boolean npc(Entity e){return e instanceof LivingEntity&&BuiltInRegistries.ENTITY_TYPE.getKey(e.getType()).getNamespace().equals("customnpcs");}
 static String label(RuralRules.Role r){return switch(r){case FARMER->"农夫";case COOK->"家庭主妇／农妇";case HUNTER->"猎户";case MERCHANT->"农村头人";case PROCUREMENT->"采购商";case BAKER->"烘焙师";case SUPPLIER->"工坊生产者";case ARTISAN->"维修工匠";default->"普通居民";};}
 static String kind(RuralRules.Role r){return switch(r){case FARMER->"farmer";case COOK->"cook";case HUNTER->"hunter";case MERCHANT->"merchant";case PROCUREMENT->"procurement";case BAKER->"baker";case SUPPLIER->"supplier";case ARTISAN->"artisan";default->"";};}
 static Template defaults(RuralRules.Role role){var t=new Template();t.role=role;t.name=label(role);t.female=role==RuralRules.Role.COOK;t.willingness=WorkHours.willingness(role==RuralRules.Role.ARTISAN?"工匠":role==RuralRules.Role.FARMER?"农夫":label(role));return t;}
 static boolean localSkin(String skin){if(skin==null||skin.length()>256||skin.contains("://")||skin.contains(".."))return false;if(skin.isEmpty())return true;var id=ResourceLocation.tryParse(skin);return id!=null&&!id.getPath().startsWith("/");}
 static void validate(Template t){CityEconomy.require(t!=null&&t.schema==1&&ROLES.contains(t.role)&&t.name!=null&&!t.name.isBlank()&&t.name.length()<=32&&t.name.chars().noneMatch(Character::isISOControl),"模板姓名或职业无效");CityEconomy.require(localSkin(t.skin),"皮肤需为本地资源路径");var h=new WorkHours.Config();h.start=t.start;h.end=t.end;h.nightStart=t.nightStart;h.nightEnd=t.nightEnd;h.willingness=t.willingness;WorkHours.validate(h);CityEconomy.require(t.huntRadius>=64&&t.huntRadius<=256,"猎户活动范围须为64—256格");}
 static Template read(ItemStack stack){var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(!tag.contains(KEY))return defaults(RuralRules.Role.FARMER);var t=CityEconomy.JSON.fromJson(tag.getString(KEY),Template.class);validate(t);return t;}
 static void store(ItemStack stack,Template t){validate(t);var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();tag.putString(KEY,CityEconomy.JSON.toJson(t));stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));}
 static Template capture(MinecraftServer s,LivingEntity entity){var p=RuralSettlement.get(s).state.people.get(entity.getUUID());CityEconomy.require(p!=null&&!p.dead&&ROLES.contains(p.role),"这个NPC尚未登记职业；可先在职业预设中选择");var t=defaults(p.role);t.name=p.name;t.female=p.female;t.huntRadius=p.huntRadius;var h=WorkHours.config(s,p.id);t.start=h.start;t.end=h.end;t.nightStart=h.nightStart;t.nightEnd=h.nightEnd;t.willingness=h.willingness;
  try{var display=entity.getClass().getField("display").get(entity);String skin=(String)display.getClass().getMethod("getSkinTexture").invoke(display);if(localSkin(skin))t.skin=skin;}catch(ReflectiveOperationException ignored){}validate(t);return t;
 }
 public static void entity(PlayerInteractEvent.EntityInteract e){if(e.getHand()!=InteractionHand.MAIN_HAND||!wand(e.getEntity().getMainHandItem())||!e.getEntity().isShiftKeyDown())return;e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);if(e.getEntity() instanceof ServerPlayer p)try{access(p);CityEconomy.require(npc(e.getTarget()),"请潜行右键自定义NPC");open(p,e.getTarget().getUUID(),e.getTarget().blockPosition());}catch(RuntimeException ex){say(p,ex.getMessage());}}
 public static void block(PlayerInteractEvent.RightClickBlock e){if(e.getHand()!=InteractionHand.MAIN_HAND||!wand(e.getItemStack())||!e.getEntity().isShiftKeyDown())return;e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);if(e.getEntity() instanceof ServerPlayer p)try{access(p);open(p,null,e.getPos().relative(e.getFace()));}catch(RuntimeException ex){say(p,ex.getMessage());}}
 static BlockPos airAnchor(net.minecraft.world.entity.player.Player p){return p.blockPosition().relative(p.getDirection(),2);}
 public static void air(PlayerInteractEvent.RightClickItem e){if(e.getHand()!=InteractionHand.MAIN_HAND||!wand(e.getItemStack()))return;e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);if(e.getEntity() instanceof ServerPlayer p)try{access(p);open(p,null,airAnchor(p));}catch(RuntimeException ex){say(p,ex.getMessage());}}
 static void open(ServerPlayer p,UUID id,BlockPos at){var session=new Session(id,at.immutable(),p.level().dimension().location().toString(),++serial,p.server.overworld().getGameTime()+12000);sessions.put(p.getUUID(),session);Template t;String message="";try{t=read(p.getMainHandItem());}catch(RuntimeException ex){t=defaults(RuralRules.Role.FARMER);message="旧模板不可读取，已显示默认值；原物品数据未覆盖，可重新保存修复";}var c=id==null?RuralTools.city(p.serverLevel(),at):CityNpcBridge.home(CityData.get(p.server),id);if(c==null)c=RuralTools.city(p.serverLevel(),at);if(id!=null&&p.serverLevel().getEntity(id) instanceof LivingEntity living&&RuralSettlement.get(p.server).state.people.containsKey(id))t=capture(p.server,living);snapshot(p,session,c,t,message);}
 static void say(ServerPlayer p,String text){p.sendSystemMessage(Component.literal("[职业模板] "+text));}
 static RuralSettlement.Site nearest(MinecraftServer s,CityData.City c,BlockPos at,UUID worker,RuralRules.Role role){return RuralSettlement.get(s).state.sites.values().stream().filter(v->c.id.equals(v.city)&&kind(role).equals(v.kind)&&(v.worker==null||Objects.equals(v.worker,worker))&&BlockPos.of(v.pos).distSqr(at)<=1024&&RuralTools.available(s,v)).min(Comparator.<RuralSettlement.Site>comparingInt(v->Objects.equals(v.worker,worker)?0:1).thenComparingDouble(v->BlockPos.of(v.pos).distSqr(at))).orElse(null);}
 static UUID workshop(MinecraftServer s,CityData.City c,BlockPos at,UUID id){return c.housing.houses.entrySet().stream().filter(entry->{var h=entry.getValue();var building=c.buildings.get(entry.getKey());return h.stage.equals("BUILT")&&(h.workers.contains(id)||h.workers.size()<h.workerLimit)&&building!=null&&building.type().equals("工坊")&&building.bounds().contains(at)&&h.baseline.entrySet().stream().anyMatch(v->{var site=RuralSettlement.get(s).state.sites.get(RuralSettlement.key(c.id,v.getKey()));return CityBlockRules.workstation(CityMaintenance.decode(v.getValue()))&&(site==null||site.worker==null||Objects.equals(site.worker,id));});}).map(Map.Entry::getKey).findFirst().orElse(null);}
 static void preflight(MinecraftServer s,CityData.City c,LivingEntity actor,BlockPos at,Template t){validate(t);CityEconomy.require(c.includes(at),"目标必须位于所选聚落内");var d=RuralSettlement.get(s);var person=actor==null?null:d.state.people.get(actor.getUUID());var home=actor==null?null:CityNpcBridge.home(CityData.get(s),actor.getUUID());CityEconomy.require(home==null||home.id.equals(c.id),"不能借复制模板迁移已有居民；先处理所属聚落");if(person!=null){CityEconomy.require(!person.dead&&person.age.ordinal()>=2,"仅可设计在世成人");CityEconomy.require(person.role==RuralRules.Role.NONE||person.role==t.role,"已有职业请用原职业编辑器转职，避免改变经营资产归属");}else CityEconomy.require(d.state.people.size()<512,"居民数量已达上限");
  UUID id=actor==null?null:actor.getUUID();if(person!=null)CityEconomy.require(d.state.families.containsKey(person.family)&&c.id.equals(d.state.families.get(person.family).city),"现有家庭归属不一致，请先检查居民档案");
  CityEconomy.require(CityEconomy.get(s).state.production.stream().noneMatch(j->j.enabled&&Objects.equals(j.worker,id)),"这个NPC仍有旧生产岗位，请先用原编辑器停用");
  var life=CityEconomy.get(s).state.living.get(id);CityEconomy.require(life==null||!life.enabled||!life.guard,"这个NPC仍在担任守卫，请先用原编辑器处理职业");
  if(t.role==RuralRules.Role.ARTISAN)CityEconomy.require(workshop(s,c,at,id)!=null,"请先在已登记且竣工的工坊内设置，工坊需要空闲工作方块");else if(t.role!=RuralRules.Role.NONE)CityEconomy.require(nearest(s,c,at,id,t.role)!=null,"32格内没有空闲的对应工作点；先摆放工作方块");
  if(Set.of(RuralRules.Role.PROCUREMENT,RuralRules.Role.BAKER,RuralRules.Role.SUPPLIER).contains(t.role)||t.role==RuralRules.Role.FARMER&&CityTrade.urban(s,c.id))CityEconomy.require(CityTrade.get(s).state.towns.containsKey(c.id),"请先用信息魔杖→城市管理→城村经济登记；职业模板不会重置城市或经营库存");
  if(t.role==RuralRules.Role.ARTISAN){CityEconomy.require(person==null||RuralSuccession.capable(person),"工匠需要健康成人");CityEconomy.require(CityEconomy.get(s).state.production.stream().noneMatch(j->j.enabled&&Objects.equals(j.worker,id)),"先解除原生产岗位");}
  if(t.role==RuralRules.Role.MERCHANT&&CityTrade.get(s).state.towns.containsKey(c.id)){var head=CityTrade.get(s).head(c.id);CityEconomy.require(head==null||Objects.equals(head.worker,id),"本村已有经营头人，请编辑原头人，避免复制经营资产");}
 }
 static void apply(MinecraftServer s,CityData.City c,LivingEntity actor,Template t){preflight(s,c,actor,actor.blockPosition(),t);var d=RuralSettlement.get(s);var e=CityEconomy.get(s);var id=actor.getUUID();c.residents.add(id);e.state.accounts.putIfAbsent(CityEconomy.person(id),0L);var person=d.enroll(s,c,id,t.name);person.name=t.name;person.female=t.female;
  if(t.role==RuralRules.Role.ARTISAN)RuralSuccession.employ(s,c,id,workshop(s,c,actor.blockPosition(),id));else {RuralSuccession.setRole(person,t.role);if(t.role!=RuralRules.Role.NONE){var site=nearest(s,c,actor.blockPosition(),id,t.role);site.worker=id;site.vacantSince=0;CityTradeLab.attach(s,c,site,person);if(t.role==RuralRules.Role.FARMER&&CityTrade.urban(s,c.id)){var trade=CityTrade.get(s);if(trade.state.businesses.values().stream().noneMatch(b->b.worker.equals(id))){var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=c.id;b.worker=id;b.site=site.pos;b.kind="urban_farmer";b.account="trade:"+b.id;trade.state.businesses.put(b.id,b);trade.setDirty();}}
    for(var box:d.state.boxes.values())if(box.city.equals(c.id)&&box.linked&&box.site==site.pos&&box.stock.family==null)box.stock.family=person.family;
   }}
  if(t.role==RuralRules.Role.MERCHANT&&CityTrade.get(s).state.towns.containsKey(c.id)&&CityTrade.get(s).head(c.id)==null){var trade=CityTrade.get(s);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=c.id;b.owner=id;b.worker=id;b.site=nearest(s,c,actor.blockPosition(),id,t.role).pos;b.kind="head";b.account=CityEconomy.person(id);trade.state.businesses.put(b.id,b);trade.setDirty();}
  var hours=WorkHours.config(s,id);hours.start=t.start;hours.end=t.end;hours.nightStart=t.nightStart;hours.nightEnd=t.nightEnd;hours.willingness=t.willingness;hours.revision++;person.huntRadius=t.huntRadius;
  CityActorSkins.apply(s,person,actor);try{var display=actor.getClass().getField("display").get(actor);display.getClass().getMethod("setName",String.class).invoke(display,t.name);if(!t.skin.isEmpty())display.getClass().getMethod("setSkinTexture",String.class).invoke(display,t.skin);actor.getClass().getField("updateClient").setBoolean(actor,true);}catch(ReflectiveOperationException ignored){actor.setCustomName(Component.literal(t.name));}
  d.state.revision++;d.setDirty();e.setDirty();CityData.get(s).changed(c);
 }
 static void snapshot(ServerPlayer p,Session session,CityData.City c,Template template,String message){var t=new CompoundTag();t.putBoolean("NpcDesigner",true);t.putLong("Token",session.token);t.putString("Target",session.npc==null?"":session.npc.toString());t.putString("Template",CityEconomy.JSON.toJson(template));t.putString("Message",message);t.putString("City",c==null?"":c.id.toString());t.putLong("CityRevision",c==null?0:c.revision);var list=new net.minecraft.nbt.ListTag();for(var v:CityData.get(p.server).cities())if(v.dimension.equals(session.dimension)&&(p.hasPermissions(2)||v.owner.equals(p.getUUID()))){var n=new CompoundTag();n.putString("Id",v.id.toString());n.putString("Name",v.name);n.putLong("Revision",v.revision);list.add(n);}t.put("Cities",list);
  String status=c==null?"先在城市沙盘登记聚落范围":!c.includes(session.anchor)?"目标不在这个聚落内":template.role==RuralRules.Role.NONE?"居民不需要工作点":template.role==RuralRules.Role.ARTISAN?(workshop(p.server,c,session.anchor,session.npc)==null?"需要已登记、竣工并有空位的工坊":"将使用所在工坊的空闲工作点"):Optional.ofNullable(nearest(p.server,c,session.anchor,session.npc,template.role)).map(v->"工作点："+BlockPos.of(v.pos).toShortString()).orElse("缺少空闲工作点：先在32格内放置对应工作方块");boolean ready=false;if(c!=null)try{var actor=session.npc==null?null:p.serverLevel().getEntity(session.npc);preflight(p.server,c,actor instanceof LivingEntity living?living:null,actor==null?session.anchor:actor.blockPosition(),template);ready=true;}catch(RuntimeException ex){status=ex.getMessage();}t.putBoolean("Ready",ready);t.putString("Readiness",status);t.putString("RunState",c!=null&&!RuralSettlement.active(p.server,c.id)?"聚落当前暂停；保存设计不会启动模拟":"新建不带口粮和银币；生活条件由聚落统一配置");PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(t));
 }
 static void request(ServerPlayer p,CityNetwork.Request r){if(CityNpcSetup.handles(r.op())){CityNpcSetup.request(p,r);return;}try{access(p);var session=sessions.get(p.getUUID());CityEconomy.require(session!=null&&session.token==r.revision()&&session.expires>=p.server.overworld().getGameTime()&&session.dimension.equals(p.level().dimension().location().toString()),"设计窗口已过期，请重新打开复制魔杖");var c=r.city().isEmpty()?null:CityData.get(p.server).require(UUID.fromString(r.city()));if(c!=null)CityService.checkEditor(p,c,(long)r.x()<<32|(r.y()&0xffffffffL));Template template=CityEconomy.JSON.fromJson(r.value(),Template.class);validate(template);String message="";
  switch(r.op()){
   case "careerreset"->{template=defaults(template.role);message="已恢复该职业默认设计；人物状态不变";}
   case "careersave"->{store(p.getMainHandItem(),template);message="职业模板已保存在这根复制魔杖，可复制魔杖物品保留多个模板";}
   case "careerload"->{template=read(p.getMainHandItem());message="已读取魔杖模板；尚未修改人物";}
   case "careercapture"->{CityEconomy.require(session.npc!=null&&p.serverLevel().getEntity(session.npc) instanceof LivingEntity,"请先潜行右键需要取样的NPC");template=capture(p.server,(LivingEntity)p.serverLevel().getEntity(session.npc));store(p.getMainHandItem(),template);message="已取样职业、皮肤和作息；身份、家庭、财产及进度没有复制";}
   case "careerapply","careerspawn"->{CityEconomy.require(c!=null,"先选择聚落");LivingEntity actor=null;if(r.op().equals("careerapply")){CityEconomy.require(session.npc!=null&&p.serverLevel().getEntity(session.npc) instanceof LivingEntity,"请潜行右键选中NPC");actor=(LivingEntity)p.serverLevel().getEntity(session.npc);CityEconomy.require(npc(actor)&&actor.isAlive()&&actor.distanceToSqr(p)<=4096,"NPC已离开，请重新选择");}else CityEconomy.require(session.npc==null,"请潜行右键地面选择新建位置");CityEconomy.require(session.anchor.distSqr(p.blockPosition())<=4096&&p.serverLevel().hasChunkAt(session.anchor),"请靠近目标位置，不会强制加载区块");preflight(p.server,c,actor,actor==null?session.anchor:actor.blockPosition(),template);
    if(actor==null){CityEconomy.require(p.serverLevel().getBlockState(session.anchor).getCollisionShape(p.serverLevel(),session.anchor).isEmpty()&&p.serverLevel().getBlockState(session.anchor.above()).getCollisionShape(p.serverLevel(),session.anchor.above()).isEmpty(),"新建位置需要两格净空");var floor=p.serverLevel().getBlockState(session.anchor.below());CityEconomy.require(!floor.getCollisionShape(p.serverLevel(),session.anchor.below()).isEmpty(),"请选有地面支撑的位置");var made=BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse("customnpcs:customnpc")).create(p.serverLevel());CityEconomy.require(made instanceof LivingEntity,"当前版本没有可用CustomNPC类型");actor=(LivingEntity)made;actor.setPos(session.anchor.getX()+.5,session.anchor.getY(),session.anchor.getZ()+.5);if(actor instanceof Mob mob)mob.setPersistenceRequired();CityEconomy.require(p.serverLevel().addFreshEntity(actor),"NPC生成失败");}
    apply(p.server,c,actor,template);RuralTools.selected.put(p.getUUID(),actor.getUUID());afterSave(p,c,actor,template);return;}
   case "careerview"->{}
   default->throw new IllegalArgumentException("未知职业模板操作");
  }snapshot(p,session,c,template,message);
 }catch(RuntimeException ex){say(p,"未执行："+ex.getMessage());var session=sessions.get(p.getUUID());if(session!=null){var c=RuralTools.city(p.serverLevel(),session.anchor);Template t;try{t=CityEconomy.JSON.fromJson(r.value(),Template.class);validate(t);}catch(RuntimeException ignored){t=defaults(RuralRules.Role.FARMER);}snapshot(p,session,c,t,"未执行："+ex.getMessage());}}}
 static Session session(ServerPlayer p,long token){access(p);var s=sessions.get(p.getUUID());CityEconomy.require(s!=null&&s.token==token&&s.expires>=p.server.overworld().getGameTime()&&s.dimension.equals(p.level().dimension().location().toString()),"设计窗口已过期，请重新打开复制魔杖");return s;}
 static void afterSave(ServerPlayer p,CityData.City c,LivingEntity actor,Template template){var s=new Session(actor.getUUID(),actor.blockPosition(),p.level().dimension().location().toString(),++serial,p.server.overworld().getGameTime()+12000);sessions.put(p.getUUID(),s);CityNpcSetup.snapshot(p,s,c,template,0,"职业NPC已保存。以下只检查条件，不会补钱、补粮或启动城市。");}
 static void logout(UUID id){sessions.remove(id);}static void clear(){sessions.clear();}
}
